import AppIntents
import AppKit
import Foundation
import UniformTypeIdentifiers

// Shortcuts actions. They run inside the app's process (the system launches Clementine in the background when it
// isn't running) and go through `ShortcutRunner`, which uses the same `BatchRunner` path as the wheel and the CLI.
// The App Intents metadata these need is generated by scripts/bundle.sh, since SwiftPM doesn't produce it.

// MARK: - Runner (no App Intents types, so the debug CLI can test it)

enum ShortcutRunner {
    enum Result {
        case file(URL)
        case text(title: String, body: String)
    }

    /// What Shortcuts lists for an action: wheel titles are format names ("PNG"), which need a verb out of context.
    static func name(of action: Action) -> String {
        if action.id == "convert.archive.extract" { return "Extract Archive" }
        if action.id.hasPrefix("archive.") { return "Archive as \(action.title)" }
        if action.mode == .convert { return "Convert to \(action.title)" }
        return action.title
    }

    /// The kind of file an action is for, to tell apart actions with the same name (three Rotates, two Joins).
    static func group(of action: Action) -> String {
        let parts = action.id.split(separator: ".")
        if parts.first == "archive" { return "Files and folders" }
        guard parts.count >= 3 else { return "Images, video and audio" }
        switch parts[1] {
        case "image": return "Images"
        case "media": return "Video and audio"
        case "video": return "Video"
        case "audio": return "Audio"
        case "pdf": return "PDF"
        case "document": return "Documents"
        case "subtitle": return "Subtitles"
        case "archive": return "Archives"
        case "metadata": return "Images, video, audio and PDF"
        default: return "Files"
        }
    }

    /// Actions that can take all of these files, wheel order, convert before tools. Hidden slices included:
    /// someone picking an action in Shortcuts wants the whole catalog.
    static func actions(for urls: [URL]) -> [Action] {
        guard !urls.isEmpty else { return ActionRegistry.all }
        let fitting = ActionRegistry.candidates(for: urls, mode: .convert) + ActionRegistry.candidates(for: urls, mode: .tools)
        return fitting.isEmpty ? ActionRegistry.all : fitting
    }

    /// `key=value` overrides, checked exactly like the CLI's `--set`.
    static func params(for action: Action, settings: [String]) throws -> ParamValues {
        var params = action.defaults
        for line in settings.flatMap({ $0.split(whereSeparator: \.isNewline) }).map(String.init) {
            let trimmed = line.trimmingCharacters(in: .whitespaces)
            if trimmed.isEmpty { continue }
            let pair = trimmed.split(separator: "=", maxSplits: 1, omittingEmptySubsequences: false).map(String.init)
            let key = pair[0].trimmingCharacters(in: .whitespaces)
            let known = action.parameters.map(\.key)
            guard pair.count == 2 else {
                throw ClementineError.message("Settings are written key=value, one per line (got \"\(trimmed)\").")
            }
            guard let parameter = action.parameters.first(where: { $0.key == key }) else {
                let hint = known.isEmpty ? "it has no settings" : "its settings are \(known.joined(separator: ", "))"
                throw ClementineError.message("\(name(of: action)) has no setting \"\(key)\" (\(hint)).")
            }
            switch CLI.parse(pair[1], for: parameter) {
            case .success(let value): params.storage[parameter.key] = value
            case .failure(let problem): throw ClementineError.message("\(key)=\(pair[1]): \(problem.message)")
            }
        }
        return params
    }

    static func run(actionID: String, inputs: [URL], settings: [String]) async throws -> [Result] {
        guard let action = ActionRegistry.find(actionID) else {
            throw ClementineError.message("Clementine has no action \"\(actionID)\".")
        }
        guard !inputs.isEmpty else { throw ClementineError.message("No files were passed to \(name(of: action)).") }
        guard inputs.count >= action.minInputs else {
            throw ClementineError.message("\(name(of: action)) needs at least \(action.minInputs) files.")
        }
        guard inputs.count <= action.maxInputs else {
            throw ClementineError.message("\(name(of: action)) works on one file at a time.")
        }
        // The wheel never offers an action for files it can't take; here the shortcut picked it, so say why it won't run.
        if let misfit = inputs.first(where: { !action.accepts(FileItem(url: $0)) }) {
            throw ClementineError.message("\(name(of: action)) doesn't work on \(misfit.lastPathComponent).")
        }
        let params = try params(for: action, settings: settings)
        let report = await BatchRunner.run(action, urls: inputs, params: params)
        if report.cancelled { throw CancellationError() }
        if let failure = report.failures.first {
            let done = report.files.count
            let note = done > 0 ? " (\(done) other file\(done == 1 ? " was" : "s were") saved)" : ""
            throw ClementineError.message("\(failure.message)\(note)")
        }
        return report.outcomes.flatMap { outcome -> [Result] in
            switch outcome.result {
            case .success(.files(let urls)): return urls.map { .file($0) }
            case .success(.text(let title, let body)): return [.text(title: title, body: body)]
            // Compress kept the original: hand it on so the rest of the shortcut still gets a file.
            case .success(.unchanged): return outcome.unit.map { .file($0) }
            case .failure: return []
            }
        }
    }

    #if DEBUG
    /// `Clementine --shortcut-run <action-id> [--set key=value]... <file>...`: runs the Shortcuts path and prints
    /// results the way the intent returns them (files as paths, text as `== title ==` blocks).
    static func handle(_ arguments: [String]) -> Bool {
        guard arguments.first == "--shortcut-run", arguments.count >= 2 else { return false }
        var rest = Array(arguments.dropFirst(2))
        var settings: [String] = [], files: [URL] = []
        while !rest.isEmpty {
            let argument = rest.removeFirst()
            if argument == "--set", !rest.isEmpty { settings.append(rest.removeFirst()) } else {
                files.append(URL(fileURLWithPath: argument).standardizedFileURL)
            }
        }
        let id = arguments[1]
        _ = NSApplication.shared // engines may touch AppKit, as in the CLI
        Task {
            do {
                for result in try await run(actionID: id, inputs: files, settings: settings) {
                    switch result {
                    case .file(let url): print(url.path)
                    case .text(let title, let body): print("== \(title) ==\n\(body)")
                    }
                }
                exit(0)
            } catch {
                fputs("error: \(error.localizedDescription)\n", stderr)
                exit(1)
            }
        }
        RunLoop.main.run()
        return true
    }
    #endif
}

// MARK: - Files in and out

/// Errors Shortcuts shows as they are (it doesn't show a LocalizedError's description by itself).
struct ShortcutError: Error, CustomLocalizedStringResourceConvertible {
    let message: String
    var localizedStringResource: LocalizedStringResource { "\(message)" }
}

enum ShortcutFiles {
    /// Clementine writes results next to the originals, so it needs real paths. Files that come without one
    /// (clipboard images, downloads made in the shortcut) are saved to a temporary folder first, and their results
    /// end up there too.
    static func materialize(_ files: [IntentFile]) throws -> [URL] {
        var scratch: URL?
        return try files.map { file in
            if let url = file.fileURL, FileManager.default.fileExists(atPath: url.path) {
                _ = url.startAccessingSecurityScopedResource() // not sandboxed, but Shortcuts may hand over scoped URLs
                return url
            }
            if scratch == nil {
                scratch = FileManager.default.temporaryDirectory
                    .appendingPathComponent("Clementine Shortcuts", isDirectory: true)
                    .appendingPathComponent(UUID().uuidString, isDirectory: true)
                try FileManager.default.createDirectory(at: scratch!, withIntermediateDirectories: true)
            }
            let name = file.filename.isEmpty ? "File" : file.filename
            let url = Output.unique(in: scratch!, sameNameAs: URL(fileURLWithPath: name))
            try file.data.write(to: url)
            return url
        }
    }

    static func output(_ results: [ShortcutRunner.Result]) -> [IntentFile] {
        results.map { result in
            switch result {
            case .file(let url):
                return IntentFile(fileURL: url, filename: url.lastPathComponent, type: UTType(filenameExtension: url.pathExtension))
            case .text(let title, let body):
                let base = (title as NSString).deletingPathExtension
                return IntentFile(data: Data(body.utf8), filename: "\(base.isEmpty ? "Result" : base).txt", type: .plainText)
            }
        }
    }

    static func run(_ actionID: String, _ files: [IntentFile], settings: [String] = []) async throws -> [IntentFile] {
        do {
            let urls = try materialize(files)
            defer { urls.forEach { $0.stopAccessingSecurityScopedResource() } }
            return output(try await ShortcutRunner.run(actionID: actionID, inputs: urls, settings: settings))
        } catch let error as CancellationError {
            throw error
        } catch {
            throw ShortcutError(message: error.localizedDescription)
        }
    }

    /// The type identifiers of these files, from their names (what `IntentParameterDependency` can see).
    static func placeholderURLs(_ files: [IntentFile]) -> [URL] {
        files.map { $0.fileURL ?? URL(fileURLWithPath: "/nonexistent").appendingPathComponent($0.filename) }
    }
}

// MARK: - Action picker

struct ClementineActionEntity: AppEntity {
    static var typeDisplayRepresentation: TypeDisplayRepresentation = "Clementine Action"
    static var defaultQuery = ClementineActionQuery()

    let id: String
    let name: String
    let group: String

    init(_ action: Action) {
        id = action.id
        name = ShortcutRunner.name(of: action)
        group = ShortcutRunner.group(of: action)
    }

    var displayRepresentation: DisplayRepresentation {
        DisplayRepresentation(title: "\(name)", subtitle: "\(group)")
    }
}

struct ClementineActionQuery: EntityStringQuery {
    /// Lets the picker offer only what fits the files already chosen in the shortcut, like the wheel does.
    @IntentParameterDependency<ConvertWithClementineIntent>(\.$files)
    var convert

    func entities(for identifiers: [String]) async throws -> [ClementineActionEntity] {
        identifiers.compactMap(ActionRegistry.find).map(ClementineActionEntity.init)
    }

    func suggestedEntities() async throws -> [ClementineActionEntity] {
        let files = convert.map { ShortcutFiles.placeholderURLs($0.files) } ?? []
        return ShortcutRunner.actions(for: files).map(ClementineActionEntity.init)
    }

    func entities(matching string: String) async throws -> [ClementineActionEntity] {
        try await suggestedEntities().filter {
            $0.name.localizedCaseInsensitiveContains(string) || $0.group.localizedCaseInsensitiveContains(string)
        }
    }
}

// MARK: - Intents

struct ConvertWithClementineIntent: AppIntent {
    static var title: LocalizedStringResource = "Convert with Clementine"
    static var description = IntentDescription(
        "Runs any Clementine conversion or tool on files and returns the results. Results are saved next to the originals.",
        categoryName: "Files")
    static var openAppWhenRun = false

    @IntentParameter(title: "Files", supportedTypeIdentifiers: ["public.item"])
    var files: [IntentFile]

    @IntentParameter(title: "Action")
    var action: ClementineActionEntity

    @IntentParameter(title: "Settings",
               description: "Optional key=value lines, the same as the command line's --set (for example level=Smallest).")
    var settings: [String]?

    static var parameterSummary: some ParameterSummary {
        Summary("\(\.$action) \(\.$files) with Clementine") {
            \.$settings
        }
    }

    func perform() async throws -> some IntentResult & ReturnsValue<[IntentFile]> {
        .result(value: try await ShortcutFiles.run(action.id, files, settings: settings ?? []))
    }
}

enum CutOutFormat: String, AppEnum {
    case png, heic, webp

    static var typeDisplayRepresentation: TypeDisplayRepresentation = "Transparent Image Format"
    static var caseDisplayRepresentations: [CutOutFormat: DisplayRepresentation] = [.png: "PNG", .heic: "HEIC", .webp: "WebP"]
}

struct RemoveBackgroundIntent: AppIntent {
    static var title: LocalizedStringResource = "Remove Background with Clementine"
    static var description = IntentDescription(
        "Cuts the subject out of photos and saves it on a transparent background, on this Mac. Results are saved next to the originals.",
        categoryName: "Images")
    static var openAppWhenRun = false

    @IntentParameter(title: "Images", supportedTypeIdentifiers: ["public.image"])
    var images: [IntentFile]

    @IntentParameter(title: "Format", default: .png)
    var format: CutOutFormat

    @IntentParameter(title: "Crop to Subject", default: false)
    var crop: Bool

    static var parameterSummary: some ParameterSummary {
        Summary("Remove the background from \(\.$images)") {
            \.$format
            \.$crop
        }
    }

    func perform() async throws -> some IntentResult & ReturnsValue<[IntentFile]> {
        let settings = ["format=\(format.rawValue)", "crop=\(crop ? "On" : "Off")"]
        return .result(value: try await ShortcutFiles.run("tool.image.removebg", images, settings: settings))
    }
}

enum ImageTarget: String, AppEnum {
    case jpeg, png, heic, webp, avif, tiff, gif, pdf

    static var typeDisplayRepresentation: TypeDisplayRepresentation = "Image Format"
    static var caseDisplayRepresentations: [ImageTarget: DisplayRepresentation] = [
        .jpeg: "JPG", .png: "PNG", .heic: "HEIC", .webp: "WebP", .avif: "AVIF", .tiff: "TIFF", .gif: "GIF", .pdf: "PDF",
    ]
}

struct ConvertImagesIntent: AppIntent {
    static var title: LocalizedStringResource = "Convert Images with Clementine"
    static var description = IntentDescription(
        "Converts images to another format. Images already in that format are passed through unchanged. Results are saved next to the originals.",
        categoryName: "Images")
    static var openAppWhenRun = false

    @IntentParameter(title: "Images", supportedTypeIdentifiers: ["public.image"])
    var images: [IntentFile]

    @IntentParameter(title: "Format", default: .jpeg)
    var format: ImageTarget

    static var parameterSummary: some ParameterSummary {
        Summary("Convert \(\.$images) to \(\.$format)")
    }

    func perform() async throws -> some IntentResult & ReturnsValue<[IntentFile]> {
        let aliases = ImageFormat(rawValue: format.rawValue)?.aliases ?? []
        // A shortcut converting a mixed batch shouldn't fail on the ones that are already right.
        let already = images.filter { aliases.contains(($0.filename as NSString).pathExtension.lowercased()) }
        let todo = images.filter { !aliases.contains(($0.filename as NSString).pathExtension.lowercased()) }
        let converted = todo.isEmpty ? [] : try await ShortcutFiles.run("convert.image.\(format.rawValue)", todo)
        return .result(value: already + converted)
    }
}
